using System;using System.Linq;using System.IO;using System.Reflection;using Verse;using Verse.AI;using PlayableRecreation;using PlayableRecreation.UI;using PRQA;
public static class Command{public static string Run(){Host.Watch=null;foreach(var w in Find.WindowStack.Windows.ToList())if(w is Dialog_MiniGame||w is Dialog_Leaderboard||w is Dialog_Difficulty||w is FloatMenu)w.Close();TogetherMatch.Reset();var p=((Pawn[])Host.State["pair"])[0];var boards=(Thing[])Host.State["extensionBoards"];var f=BindingFlags.Instance|BindingFlags.NonPublic;string log=Host.Root+"/single-workers-r2.txt";File.WriteAllText(log,"Together ON, choose difficulty through actual Dialog_Difficulty.Start callback.\n");int i=0,start=0,stage=0;Action begin=()=>{p.drafter.Drafted=false;p.jobs.EndCurrentJob(JobCondition.InterruptForced);var b=boards[i];p.Position=GenRadial.RadialCellsAround(b.Position,5,true).First(c=>c.InBounds(b.Map)&&c.Standable(b.Map)&&!c.AdjacentTo8WayOrInside(b));p.Notify_Teleported();p.needs.food.CurLevelPercentage=1;p.needs.rest.CurLevelPercentage=1;b.TryGetComp<CompMiniGame>().CompFloatMenuOptions(p).First().action();stage=0;start=Find.TickManager.TicksGame;};begin();Host.Watch=()=>{int e=Find.TickManager.TicksGame-start;var difficulty=Find.WindowStack.Windows.OfType<Dialog_Difficulty>().FirstOrDefault();var mini=Find.WindowStack.Windows.OfType<Dialog_MiniGame>().FirstOrDefault();if(stage==0&&difficulty!=null){typeof(Dialog_Difficulty).GetMethod("Start",f).Invoke(difficulty,new object[]{1});stage=1;start=Find.TickManager.TicksGame;}else if(stage==1&&(mini!=null||e>900)){File.AppendAllText(log,boards[i].def.defName+" opened="+(mini!=null)+" worker="+(mini==null?null:typeof(Dialog_MiniGame).GetField("worker",f).GetValue(mini)?.GetType().Name)+" opponent="+(mini==null?null:typeof(Dialog_MiniGame).GetField("opponentPawn",f).GetValue(mini))+"\n");mini?.Close();i++;if(i==boards.Length){Host.Watch=null;Find.TickManager.CurTimeSpeed=TimeSpeed.Paused;}else begin();}};Find.TickManager.CurTimeSpeed=TimeSpeed.Superfast;return "Start all three single-capacity game workers with together still ON.";}}
